var out=[];doc.pages.filter(function(p){return /^Proto iOS/.test(p.name)}).forEach(function(p){p.layers.filter(function(s){return /^Screen\/ios\/(Light|Dark)\/Clean\/(signin|home|conversation(--approval|--menu|--delete)?|search|activity(--work)?)$/.test(s.name)}).forEach(function(s){var b=s.layers.find(function(l){return l.name==='body'});out.push({page:p.name,name:s.name,id:s.id,body:b?b.layers.length:0,w:s.frame.width,h:s.frame.height})})});H.out(out);